SELECT * FROM oa_schedule_event
WHERE deleted = '0'
AND room_id = #{roomId}
AND recurrence_role != 'SERIES' AND status IN ('PLANNED','IN_PROGRESS','COMPLETED')
AND approval_status NOT IN ('DRAFT','REJECTED','CANCELLED')
AND start_time < #{endTime} AND DATE_ADD(end_time, INTERVAL buffer_minutes_snapshot MINUTE) > #{startTime}

SELECT * FROM oa_schedule_event
WHERE deleted = '0'
AND room_id = #{roomId}
AND event_id != #{excludeEventId}
AND recurrence_role != 'SERIES' AND status IN ('PLANNED','IN_PROGRESS','COMPLETED')
AND approval_status NOT IN ('DRAFT','REJECTED','CANCELLED')
AND start_time < #{endTime} AND DATE_ADD(end_time, INTERVAL buffer_minutes_snapshot MINUTE) > #{startTime}

SELECT * FROM oa_schedule_event 
WHERE deleted = '0' 
AND recurrence_role != 'SERIES' AND status NOT IN ('CANCELLED','NOT_HELD')
AND start_time < #{endDate} 
AND end_time > #{startDate}
AND (
   creator_id = #{userId} 
   OR (JSON_VALID(attendees) AND (JSON_CONTAINS(attendees, CAST(#{userId} AS JSON)) OR JSON_CONTAINS(attendees, JSON_QUOTE(CAST(#{userId} AS CHAR)))))
) 
ORDER BY start_time ASC

SELECT * FROM oa_schedule_event 
WHERE deleted = '0' 
AND room_id = #{roomId} 
AND recurrence_role != 'SERIES' AND status IN ('PLANNED','IN_PROGRESS','COMPLETED')
AND approval_status NOT IN ('DRAFT','REJECTED','CANCELLED')
AND start_time < #{dayEnd} 
AND DATE_ADD(end_time, INTERVAL buffer_minutes_snapshot MINUTE) > #{dayStart}
ORDER BY start_time ASC
